# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TARİHÎ TİCARET YOLLARI VE ANADOLU GÜZERGÂHLARI (12.2.9)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">1. İPEK YOLU</text>\n  <text x="32" y="92" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Başlangıç:</tspan> Çin (Şian kenti)</text>\n  <text x="32" y="110" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Orta Asya:</tspan> Semerkant, Buhara,</text>\n  <text x="40" y="125" font-size="10.5" fill="#78350f">Kaşgar, Hazar Denizi havzası</text>\n  <text x="32" y="145" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Anadolu Noktaları:</tspan> Erzurum,</text>\n  <text x="40" y="160" font-size="10.5" fill="#78350f">Sivas, Konya, Bursa, Trabzon,</text>\n  <text x="40" y="175" font-size="10.5" fill="#78350f">İzmir, Antalya ve <tspan font-weight="bold">İstanbul</tspan></text>\n  <rect x="32" y="190" width="186" height="36" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="125" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">İpek, porselen, kağıt ve</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" fill="#78350f">Doğu-Batı kültür alışverişi</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">2. BAHARAT YOLU</text>\n  <text x="257" y="92" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Başlangıç:</tspan> Hindistan ve</text>\n  <text x="265" y="107" font-size="10.5" fill="#14532d">Güneydoğu Asya adaları</text>\n  <text x="257" y="127" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Deniz Hattı:</tspan> Hint Okyanusu →</text>\n  <text x="265" y="142" font-size="10.5" fill="#14532d">Kızıldeniz ve Basra Körfezi</text>\n  <text x="257" y="162" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Varış:</tspan> İskenderiye, Antakya,</text>\n  <text x="265" y="177" font-size="10.5" fill="#14532d">Trabzon → Akdeniz\'den Avrupa</text>\n  <rect x="257" y="190" width="186" height="36" rx="6" fill="#ffffff" stroke="#22c55e"/>\n  <text x="350" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Tarçın, karanfil, zencefil,</text>\n  <text x="350" y="220" text-anchor="middle" font-size="10" fill="#14532d">tütsü, ilaç ve değerli taşlar</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">3. KRAL YOLU VE DİĞERLERİ</text>\n  <text x="482" y="92" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kral Yolu:</tspan> Lidya başkenti</text>\n  <text x="490" y="107" font-size="10.5" fill="#1e3a8a"><tspan font-weight="bold">Sardes</tspan> (Manisa/Salihli) →</text>\n  <text x="490" y="122" font-size="10.5" fill="#1e3a8a">Gordion → Ninova → <tspan font-weight="bold">Sus</tspan> (İran)</text>\n  <text x="482" y="145" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kürk Yolu:</tspan> Karadeniz\'in</text>\n  <text x="490" y="160" font-size="10.5" fill="#1e3a8a">kuzeyinden Sibirya\'ya uzanır.</text>\n  <rect x="482" y="190" width="186" height="36" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="575" y="206" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Coğrafi Keşifler (Ümit Burnu)</text>\n  <text x="575" y="220" text-anchor="middle" font-size="10" fill="#1e3a8a">ile eski önemini kaybetmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ANADOLU TİCARET MİMARİSİ VE MODERN DEMİR İPEK YOLU</text>\n  <rect x="25" y="46" width="310" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Selçuklu ve Osmanlı Ticaret Altyapısı</text>\n  <text x="38" y="92" font-size="11" fill="#581c87">• <tspan font-weight="bold">Kervansaraylar ve Hanlar:</tspan> Konaklama,</text>\n  <text x="48" y="108" font-size="10.5" fill="#581c87">güvenlik, bakım ve devlet sigortası sistemi</text>\n  <text x="48" y="124" font-size="10.5" fill="#581c87">(Sultan Hanı, Karatay Hanı, Koza Han).</text>\n  <text x="38" y="148" font-size="11" fill="#581c87">• <tspan font-weight="bold">Liman Kentleri:</tspan> Antalya, Alanya, Sinop,</text>\n  <text x="48" y="164" font-size="10.5" fill="#581c87">Samsun, Trabzon ve İzmir limanları.</text>\n  <text x="38" y="188" font-size="11" fill="#581c87">• <tspan font-weight="bold">Derbent Teşkilatı:</tspan> Geçit ve köprülerin</text>\n  <text x="48" y="204" font-size="10.5" fill="#581c87">güvenliğini sağlayan ticaret koruma ağı.</text>\n  <text x="38" y="226" font-size="10.5" font-weight="bold" fill="#7e22ce">Süveyş Kanalı (1869) → Akdeniz\'i canlandırdı!</text>\n  <rect x="355" y="46" width="320" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Modern İpek Yolu (Orta Koridor / BTK)</text>\n  <rect x="370" y="84" width="290" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="515" y="102" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Bakü – Tiflis – Kars (BTK) Demiryolu</text>\n  <text x="515" y="118" text-anchor="middle" font-size="10" fill="#1e3a8a">Hazar geçişli Orta Koridorun omurgası (Demir İpek Yolu)</text>\n  <rect x="370" y="136" width="290" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="515" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Marmaray ve Boğaz Köprüleri</text>\n  <text x="515" y="170" text-anchor="middle" font-size="10" fill="#1e3a8a">Pekin\'den Londra\'ya kesintisiz demiryolu bağlantısı</text>\n  <rect x="370" y="188" width="290" height="40" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="515" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Kuşak ve Yol Projesi\'nde Türkiye:</text>\n  <text x="515" y="220" text-anchor="middle" font-size="10" fill="#1e3a8a">Asya ile Avrupa arasında en güvenli ve kısa transit hat</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRKİYE\'NİN ENERJİ KORİDORU ROLÜ: BORU HATLARI</text>\n  <rect x="25" y="48" width="310" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Ham Petrol Boru Hatları</text>\n  <rect x="40" y="86" width="280" height="65" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="180" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">1. Bakü – Tiflis – Ceyhan (BTC)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="10" fill="#7f1d1d">Azerbaycan (Hazar) petrolünü Gürcistan</text>\n  <text x="180" y="137" text-anchor="middle" font-size="10" fill="#7f1d1d">üzerinden Adana/Ceyhan limanına ulaştırır.</text>\n  <rect x="40" y="160" width="280" height="65" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="180" y="179" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">2. Kerkük – Yumurtalık Boru Hattı</text>\n  <text x="180" y="196" text-anchor="middle" font-size="10" fill="#7f1d1d">Irak (Kerkük) petrollerini Adana/Ceyhan</text>\n  <text x="180" y="211" text-anchor="middle" font-size="10" fill="#7f1d1d">(Yumurtalık) terminalinden Akdeniz\'e taşır.</text>\n  <rect x="355" y="48" width="320" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Doğal Gaz Boru Hatları</text>\n  <rect x="370" y="86" width="290" height="65" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="515" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">1. TANAP (Trans Anadolu Doğal Gaz Hattı)</text>\n  <text x="515" y="122" text-anchor="middle" font-size="10" fill="#14532d">Azerbaycan Şahdeniz gazını Gürcistan-Türkiye</text>\n  <text x="515" y="137" text-anchor="middle" font-size="10" fill="#14532d">üzerinden Yunanistan sınırında TAP\'a bağlar.</text>\n  <rect x="370" y="160" width="290" height="65" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="515" y="179" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">2. TürkAkım ve Mavi Akım</text>\n  <text x="515" y="196" text-anchor="middle" font-size="10" fill="#14532d">Rusya doğal gazını Karadeniz tabanından</text>\n  <text x="515" y="211" text-anchor="middle" font-size="10" fill="#14532d">Samsun (Mavi Akım) ve Kıyıköy\'e (TürkAkım) taşır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
